//! The allowlisted operations (generated by build.rs from allowlist.txt and docs/api/openapi.json) and the one place
//! a request URL is built. A caller's values only ever fill a whole path segment or a query value.

use serde_json::{Map, Value};
use url::Url;

use crate::error::GatewayError;

#[derive(Debug)]
pub struct Operation {
    pub id: &'static str,
    pub method: &'static str,
    pub path: &'static str,
    pub path_params: &'static [&'static str],
    pub query_params: &'static [&'static str],
    pub has_body: bool,
}

include!(concat!(env!("OUT_DIR"), "/operations.rs"));

/// The allowlisted operation with this id, or `gateway.not_allowed`.
pub fn operation(id: &str) -> Result<&'static Operation, GatewayError> {
    OPERATIONS
        .iter()
        .find(|op| op.id == id)
        .ok_or_else(|| GatewayError::not_allowed(id))
}

/// `base` (`http://127.0.0.1:<port>/`) plus the operation's path, each `{name}` replaced by one percent-encoded segment,
/// plus the query encoded as pairs. Names the contract does not list for the operation are refused, not dropped.
pub fn build_url(
    base: &Url,
    op: &Operation,
    path: &Map<String, Value>,
    query: &Map<String, Value>,
) -> Result<Url, GatewayError> {
    for name in path.keys() {
        if !op.path_params.contains(&name.as_str()) {
            return Err(GatewayError::bad_parameter(
                name,
                "not a path parameter of this operation",
            ));
        }
    }
    for name in query.keys() {
        if !op.query_params.contains(&name.as_str()) {
            return Err(GatewayError::bad_parameter(
                name,
                "not a query parameter of this operation",
            ));
        }
    }
    let mut url = base.clone();
    {
        let mut segments = url.path_segments_mut().map_err(|_| {
            GatewayError::gateway(500, "contract_mismatch", "bad engine address", Value::Null)
        })?;
        segments.clear();
        for part in op.path.split('/').filter(|s| !s.is_empty()) {
            match part.strip_prefix('{').and_then(|p| p.strip_suffix('}')) {
                Some(name) => {
                    let value = scalar(name, path.get(name))?
                        .ok_or_else(|| GatewayError::bad_parameter(name, "required"))?;
                    // a slash is refused, not only encoded: the engine's server decodes %2F back to `/` before routing
                    if value.is_empty()
                        || value == "."
                        || value == ".."
                        || value.contains(['/', '\\'])
                    {
                        return Err(GatewayError::bad_parameter(
                            name,
                            "not a valid path segment",
                        ));
                    }
                    segments.push(&value); // percent-encodes `?`, `#` and `%` within the one segment
                }
                None => {
                    segments.push(part);
                }
            }
        }
    }
    url.set_query(None);
    if !query.is_empty() {
        let mut pairs = url.query_pairs_mut();
        for (name, value) in query {
            match value {
                Value::Array(items) => {
                    for item in items {
                        if let Some(v) = scalar(name, Some(item))? {
                            pairs.append_pair(name, &v);
                        }
                    }
                }
                _ => {
                    if let Some(v) = scalar(name, Some(value))? {
                        pairs.append_pair(name, &v);
                    }
                }
            }
        }
    }
    Ok(url)
}

/// A parameter value as text: strings as they are, numbers and booleans written out, null as absent.
fn scalar(name: &str, value: Option<&Value>) -> Result<Option<String>, GatewayError> {
    match value {
        None | Some(Value::Null) => Ok(None),
        Some(Value::String(s)) => Ok(Some(s.clone())),
        Some(Value::Number(n)) => Ok(Some(n.to_string())),
        Some(Value::Bool(b)) => Ok(Some(b.to_string())),
        Some(_) => Err(GatewayError::bad_parameter(
            name,
            "must be a string, number or boolean",
        )),
    }
}

#[cfg(test)]
mod tests {
    use serde_json::json;

    use super::*;

    fn base() -> Url {
        Url::parse("http://127.0.0.1:4321/").unwrap()
    }

    fn map(v: Value) -> Map<String, Value> {
        v.as_object().unwrap().clone()
    }

    #[test]
    fn the_table_holds_the_allowlist_with_the_contracts_method_and_path() {
        let op = operation("get_job").unwrap();
        assert_eq!(
            (op.method, op.path, op.path_params),
            ("GET", "/v1/jobs/{job_id}", &["job_id"][..])
        );
        assert!(operation("saves_back_up").unwrap().has_body);
        assert_eq!(CONTRACT_MAJOR, "1");
    }

    #[test]
    fn an_operation_off_the_allowlist_is_refused() {
        let err = operation("mods_delete_profile").unwrap_err();
        assert_eq!(
            (err.status, err.code.as_str()),
            (403, "gateway.not_allowed")
        );
    }

    #[test]
    fn a_path_value_fills_exactly_one_segment() {
        let op = operation("get_job").unwrap();
        for (value, expected) in [
            ("abc", "/v1/jobs/abc"),
            ("%2e%2e", "/v1/jobs/%252e%252e"),
            ("%2F", "/v1/jobs/%252F"),
            ("x?y=1", "/v1/jobs/x%3Fy=1"),
            ("x#frag", "/v1/jobs/x%23frag"),
        ] {
            let url =
                build_url(&base(), op, &map(json!({ "job_id": value })), &Map::new()).unwrap();
            assert_eq!(url.path(), expected, "value {value:?}");
            assert_eq!(
                (url.query(), url.fragment()),
                (None, None),
                "value {value:?}"
            );
            assert_eq!(url.host_str(), Some("127.0.0.1"));
        }
    }

    #[test]
    fn dot_segments_and_empty_values_are_refused() {
        let op = operation("get_job").unwrap();
        for value in ["", ".", "..", "../health", "a/b", "a\\b", "..\\health"] {
            let err =
                build_url(&base(), op, &map(json!({ "job_id": value })), &Map::new()).unwrap_err();
            assert_eq!(err.code, "gateway.bad_parameter", "value {value:?}");
        }
        let missing = build_url(&base(), op, &Map::new(), &Map::new()).unwrap_err();
        assert_eq!(missing.code, "gateway.bad_parameter");
    }

    #[test]
    fn names_the_contract_does_not_list_are_refused() {
        let op = operation("get_job").unwrap();
        let err = build_url(
            &base(),
            op,
            &map(json!({ "job_id": "a", "other": "b" })),
            &Map::new(),
        )
        .unwrap_err();
        assert_eq!(err.code, "gateway.bad_parameter");
        let err = build_url(
            &base(),
            op,
            &map(json!({ "job_id": "a" })),
            &map(json!({ "x": "1" })),
        )
        .unwrap_err();
        assert_eq!(err.code, "gateway.bad_parameter");
    }

    #[test]
    fn objects_cannot_be_path_values() {
        let op = operation("get_job").unwrap();
        let err = build_url(
            &base(),
            op,
            &map(json!({ "job_id": { "a": 1 } })),
            &Map::new(),
        )
        .unwrap_err();
        assert_eq!(err.code, "gateway.bad_parameter");
    }
}
